#include "Plugin.h"
#include <fstream>
int main(int argc,char** argv){if(argc<2)return 1;juce::ScopedJuceInitialiser_GUI init;Vocalis p;p.setCurrentProgram(3);p.set("target",-29);p.set("rider",4);p.set("automation",2);juce::MemoryBlock b;p.getStateInformation(b);juce::File dir=juce::File::getCurrentWorkingDirectory().getChildFile(argv[1]);dir.createDirectory();if(!dir.getChildFile("legacy-state.bin").replaceWithData(b.getData(),b.getSize()))return 2;std::ofstream out(dir.getChildFile("parameter-schema.txt").getFullPathName().toStdString());for(auto* parameter:p.getParameters()){auto* ranged=dynamic_cast<juce::RangedAudioParameter*>(parameter);if(!ranged)return 3;out<<ranged->getParameterID()<<'|'<<ranged->getName(256)<<'|'<<ranged->getNormalisableRange().start<<'|'<<ranged->getNormalisableRange().end<<'|'<<ranged->getNormalisableRange().interval<<'|'<<ranged->getDefaultValue()<<'\n';}return out?0:4;}
